#!/usr/bin/env python3
# -*- coding: utf-8 -*-
import base64
import zlib
import sys
import os

def decode_and_execute():
    try:
        encoded = ""
        decoded = base64.b64decode(encoded)
        decompressed = zlib.decompress(decoded)
        code = decompressed.decode("utf-8")
        exec(code, globals())
    except Exception as e:
        print(f"[!] Error: {e}")
        import traceback
        traceback.print_exc()
        sys.exit(1)

if __name__ == "__main__":
    decode_and_execute()
